#!/bin/bash
# macvm otomatik onarim (tek dosya). Kullanim (root, tercihen BAKIM MODUNDA):
#   bash macvm-fix.sh            -> her seyi kontrol et ve onar
#   bash macvm-fix.sh --normal   -> ayrica GPU modunu kapat (ekran gelmiyorsa)
# macOS diskine ve icindeki verilere dokunmaz.
set -e
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH"
[ "$(id -u)" -eq 0 ] || { echo "root olarak calistir:  su -   sonra   bash macvm-fix.sh"; exit 1; }
D=/root/macvm-onarim
rm -rf "$D"; mkdir -p "$D"
sed -n '/^__ARSIV__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$D"
exec bash "$D/macvm/fix.sh" "$@"
